def solve(inputs: dict) -> float:
    seed = inputs['SEED']
    a = inputs['A']
    b = inputs['B']
    m = inputs['M']
    k = inputs['K']

    x = seed
    for _ in range(k):
        x = (a * x + b) % m

    return float(x)

